import { Mesh } from "@babylonjs/core/Meshes/mesh";
import { useState, useRef } from "react";
import { useBeforeRender, useScene } from "react-babylonjs";

type RotatingBoxProps = {
 rpm: number;
};

const RotatingBoxRef: React.FC<Partial<RotatingBoxProps>> = (props) => {
 const _props: RotatingBoxProps = {
   rpm: 5,
   ...props,
 };
 const { rpm } = _props;
 const scene = useScene();

 // \u4E0D\u4F7F\u7528useState\u4E86 const [y, setY] = useState(0);
 const boxRef = useRef<Mesh | null>(null);

 useBeforeRender(
   () => {
     if (!scene || !boxRef.current) return;
     const deltaTimeInMillis = scene.getEngine().getDeltaTime();
     //\u76F4\u63A5\u4FEE\u6539\u5BF9\u8C61\u7684y\u6570\u503C
     boxRef.current.rotation.y +=
       (rpm / 60) * Math.PI * 2 * (deltaTimeInMillis / 1000);
   },
   undefined,
   undefined,
   undefined,
   [rpm]
 );
 //\u6DFB\u52A0\u5F15\u7528
 return (
   <box ref={boxRef} name="box" size={2} position={new Vector3(0, 1, 0)} />
 );
};

export default RotatingBoxRef;
